/**
 * Authenticated AI-chat metadata and history endpoints.
 * All database REST calls use the caller's JWT (never service_role) so Supabase RLS
 * remains the authority for conversation/message ownership.
 */
const SUPPORTED_PROVIDERS = ["auto", "openai", "groq", "gigachat", "gemini", "mistral", "openrouter"];

/**
 * Сколько ждём внешний провайдер и сколько всего тратим на них.
 *
 * Было 7 с на вызов при 16 с на всё: нормальный ответ на 500-800 токенов у 70B
 * модели на Groq не укладывается в 7 секунд, запрос обрывался, и тьютор уходил
 * на 8B-модель Workers AI. Теперь 12 с на провайдера и 16 с на всех вместе:
 * вместе с запасным путём это укладывается в бюджет прокси (45 с).
 */
const EXTERNAL_CALL_TIMEOUT_MS = 12_000;
const EXTERNAL_TOTAL_BUDGET_MS = 16_000;

export class AiChatApiError extends Error {
  constructor(status, code, message) {
    super(message);
    this.name = "AiChatApiError";
    this.status = status;
    this.code = code;
  }
}

function cleanTitle(value) {
  const title = String(value ?? "").replace(/\s+/gu, " ").trim();
  return Array.from(title || "Новый чат").slice(0, 80).join("");
}

function normalizeProvider(value) {
  const provider = String(value ?? "auto").trim().toLowerCase();
  return SUPPORTED_PROVIDERS.includes(provider) ? provider : "auto";
}

function validateSubjectSlug(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value !== "string") throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректный предмет");
  const slug = value.trim();
  if (!slug) return null;
  if (slug.length > 120 || !/^[a-zA-Z0-9_-]+$/.test(slug)) {
    throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректный предмет");
  }
  return slug;
}

export function getAiProviderStatus(env = {}) {
  const region = String(env.AI_BACKEND_REGION || "ru").trim().toLowerCase();
  const proxyReady = Boolean(env.GEMINI_VERCEL_PROXY_URL && env.GEMINI_VERCEL_PROXY_SECRET);
  const geminiBlocked = region === "ru" && !proxyReady;
  const providers = {
    openai: {
      configured: Boolean(env.OPENAI_API_KEY),
      model: env.OPENAI_MODEL || "gpt-4.1-mini",
      available: Boolean(env.OPENAI_API_KEY),
      reason: null,
    },
    groq: {
      configured: Boolean(env.GROQ_API_KEY),
      model: env.GROQ_MODEL || "openai/gpt-oss-20b",
      available: Boolean(env.GROQ_API_KEY),
      reason: null,
    },
    gigachat: {
      configured: Boolean(env.GIGACHAT_CREDENTIALS || env.GIGACHAT_ACCESS_TOKEN || env.LLM_PRIMARY_API_KEY),
      model: env.GIGACHAT_MODEL || "GigaChat-2-Max",
      available: Boolean(env.GIGACHAT_CREDENTIALS || env.GIGACHAT_ACCESS_TOKEN || env.LLM_PRIMARY_API_KEY),
      reason: null,
    },
    gemini: {
      configured: Boolean(env.GEMINI_API_KEY),
      model: env.GEMINI_MODEL || "gemini-3.6-flash",
      available: Boolean(env.GEMINI_API_KEY) && !geminiBlocked,
      reason: geminiBlocked
        ? "Gemini недоступен из региона backend (RU) без настроенного регионального прокси."
        : null,
    },
    mistral: {
      configured: Boolean(env.MISTRAL_API_KEY),
      model: env.MISTRAL_MODEL || "mistral-small-latest",
      available: Boolean(env.MISTRAL_API_KEY),
      reason: null,
    },
    openrouter: {
      configured: Boolean(env.OPENROUTER_API_KEY && env.OPENROUTER_MODEL),
      model: env.OPENROUTER_MODEL || "",
      available: Boolean(env.OPENROUTER_API_KEY && env.OPENROUTER_MODEL),
      reason: null,
    },
  };
  // Выбор модели в тьюторе: каждый провайдер публикует свой список моделей.
  // Живой список (listProviderModels из /ai/providers) подменяет статический,
  // поэтому resolveProviderModel должен принимать и живые имена моделей.
  for (const [id, entry] of Object.entries(providers)) {
    entry.models = PROVIDER_MODELS[id] || [];
  }
  const configuredDefault = String(env.AI_CHAT_PRIMARY_PROVIDER || "groq").trim().toLowerCase();
  const defaultProvider = ["auto", ...Object.keys(providers)].includes(configuredDefault) ? configuredDefault : "auto";
  return { region, providers, default: defaultProvider };
}

/**
 * Известные модели по провайдерам для выбора в тьюторе. Список — подсказка,
 * не жёсткое ограничение: настроенная в env модель провайдера тоже валидна
 * (см. resolveProviderModel), чтобы секреты вроде GROQ_MODEL не ломали выбор.
 */
export const PROVIDER_MODELS = {
  openai: ["gpt-4.1-mini", "gpt-4.1", "gpt-4o-mini"],
  groq: ["openai/gpt-oss-120b", "openai/gpt-oss-20b", "llama-3.3-70b-versatile", "llama-3.1-8b-instant"],
  gigachat: ["GigaChat-2-Max", "GigaChat-2-Pro", "GigaChat-2", "GigaChat"],
  gemini: ["gemini-3.6-flash", "gemini-2.0-flash", "gemini-2.5-flash"],
  mistral: ["mistral-small-latest", "mistral-medium-latest", "mistral-large-latest"],
  openrouter: ["openrouter/auto", "openai/gpt-4o-mini", "anthropic/claude-3.5-haiku"],
};

/**
 * Валидирует выбранную студентом модель: принимает её, если она есть в списке
 * провайдера, в живом списке (allowed) или совпадает с настроенной на воркере
 * моделью этого провайдера. Иначе возвращает null — вызывающий оставит
 * env-дефолт.
 */
export function resolveProviderModel(env = {}, providerId, requested, allowed) {
  const provider = String(providerId || "").trim().toLowerCase();
  const model = String(requested || "").trim();
  if (!provider || !model || model.length > 80) return null;
  if (Array.isArray(allowed) && allowed.includes(model)) return model;
  const staticAllowed = PROVIDER_MODELS[provider] || [];
  if (staticAllowed.includes(model)) return model;
  const status = getAiProviderStatus(env).providers?.[provider];
  if (status && status.model && status.model === model) return model;
  return null;
}

function requireCaller(request, env, userId) {
  const authorization = request.headers.get("authorization") || "";
  if (!/^Bearer\s+\S+$/i.test(authorization)) {
    throw new AiChatApiError(401, "UNAUTHORIZED", "Authentication required");
  }
  if (!userId || typeof userId !== "string") {
    throw new AiChatApiError(401, "UNAUTHORIZED", "Authentication required");
  }
  const key = String(env.SUPABASE_ANON_KEY || "").trim();
  let base;
  try {
    base = new URL(String(env.SUPABASE_URL || ""));
  } catch {
    throw new AiChatApiError(503, "AI_DATA_UNAVAILABLE", "ИИ-сервис временно недоступен");
  }
  if (base.protocol !== "https:" || !base.hostname.endsWith(".supabase.co") || !key) {
    throw new AiChatApiError(503, "AI_DATA_UNAVAILABLE", "ИИ-сервис временно недоступен");
  }
  return { authorization, key, origin: base.origin };
}

async function rest(request, env, userId, table, params, options = {}, fetcher = fetch) {
  const caller = requireCaller(request, env, userId);
  const url = new URL(`/rest/v1/${table}`, caller.origin);
  url.search = params.toString();
  const headers = new Headers({
    apikey: caller.key,
    authorization: caller.authorization,
    accept: "application/json",
  });
  if (options.body !== undefined) headers.set("content-type", "application/json");
  if (options.prefer) headers.set("prefer", options.prefer);
  let response;
  try {
    response = await callFetch(fetcher, url, {
      method: options.method || "GET",
      headers,
      ...(options.body !== undefined ? { body: JSON.stringify(options.body) } : {}),
      redirect: "manual",
      signal: AbortSignal.timeout(7000),
    });
  } catch {
    throw new AiChatApiError(503, "AI_DATA_UNAVAILABLE", "ИИ-сервис временно недоступен");
  }
  if (response.status >= 300 && response.status < 400) {
    throw new AiChatApiError(503, "AI_DATA_UNAVAILABLE", "ИИ-сервис временно недоступен");
  }
  if (response.status === 401) {
    throw new AiChatApiError(401, "UNAUTHORIZED", "Authentication required");
  }
  if (response.status === 404 && options.allowNotFound) return [];
  if (!response.ok) {
    // Never return PostgREST error bodies: they can contain schema or private data.
    throw new AiChatApiError(503, "AI_DATA_UNAVAILABLE", "ИИ-сервис временно недоступен");
  }
  if (response.status === 204) return [];
  try {
    const value = await response.json();
    return Array.isArray(value) ? value : value && typeof value === "object" ? value : [];
  } catch {
    throw new AiChatApiError(503, "AI_DATA_UNAVAILABLE", "ИИ-сервис временно недоступен");
  }
}

function uuidOr404(value) {
  const id = String(value || "").trim();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
    throw new AiChatApiError(404, "NOT_FOUND", "Ресурс ИИ-сервиса недоступен");
  }
  return id;
}

export async function listAiConversations(request, env, userId, fetcher = fetch) {
  const params = new URLSearchParams({
    select: "id,title,provider,model,subject_slug,created_at,updated_at",
    user_id: `eq.${userId}`,
    order: "updated_at.desc",
    limit: "100",
  });
  const items = await rest(request, env, userId, "ai_conversations", params, {}, fetcher);
  return { items: Array.isArray(items) ? items : [] };
}

export async function createAiConversation(request, env, userId, payload = {}, fetcher = fetch) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректное тело запроса");
  }
  if (payload.title !== undefined && payload.title !== null && typeof payload.title !== "string") {
    throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректное название чата");
  }
  if (payload.provider !== undefined && payload.provider !== null && typeof payload.provider !== "string") {
    throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректный AI-провайдер");
  }
  const subjectSlug = validateSubjectSlug(payload.subject_slug);
  const row = {
    user_id: userId,
    title: cleanTitle(payload.title),
    provider: normalizeProvider(payload.provider),
    subject_slug: subjectSlug,
  };
  const params = new URLSearchParams({
    select: "id,title,provider,model,subject_slug,created_at,updated_at",
  });
  const rows = await rest(request, env, userId, "ai_conversations", params, {
    method: "POST",
    body: row,
    prefer: "return=representation",
  }, fetcher);
  if (!Array.isArray(rows) || !rows[0] || typeof rows[0].id !== "string") {
    throw new AiChatApiError(503, "AI_DATA_UNAVAILABLE", "ИИ-сервис временно недоступен");
  }
  return { conversation: rows[0] };
}

export async function getAiConversation(request, env, userId, conversationId, fetcher = fetch) {
  const id = uuidOr404(conversationId);
  const conversationParams = new URLSearchParams({
    select: "id,title,provider,model,subject_slug,metadata,created_at,updated_at",
    id: `eq.${id}`,
    user_id: `eq.${userId}`,
    limit: "1",
  });
  const conversations = await rest(request, env, userId, "ai_conversations", conversationParams, {}, fetcher);
  const conversation = Array.isArray(conversations) ? conversations[0] : null;
  if (!conversation) throw new AiChatApiError(404, "NOT_FOUND", "Ресурс ИИ-сервиса недоступен");

  const messageParams = new URLSearchParams({
    select: "id,role,content,provider,model,metadata,created_at",
    conversation_id: `eq.${id}`,
    user_id: `eq.${userId}`,
    order: "created_at.asc",
    limit: "1000",
  });
  const messages = await rest(request, env, userId, "ai_messages", messageParams, {}, fetcher);
  return { conversation, messages: Array.isArray(messages) ? messages : [] };
}

export async function deleteAiConversation(request, env, userId, conversationId, fetcher = fetch) {
  const id = uuidOr404(conversationId);
  const params = new URLSearchParams({
    id: `eq.${id}`,
    user_id: `eq.${userId}`,
  });
  await rest(request, env, userId, "ai_conversations", params, {
    method: "DELETE",
    prefer: "return=minimal",
  }, fetcher);
  return { deleted: true };
}


function getAiCompletionCandidates(env, preferredProvider, userOverride) {
  // BYOM: пользовательская модель. prefer_own — своей моделью отвечаем первым,
  // при её отказе фолбэк на платформенные; явный выбор «custom» — только она.
  const preferred = String(preferredProvider || "auto").trim().toLowerCase();
  const region = String(env.AI_BACKEND_REGION || "ru").trim().toLowerCase();
  const geminiProxyReady = Boolean(env.GEMINI_VERCEL_PROXY_URL && env.GEMINI_VERCEL_PROXY_SECRET);
  const candidates = [];
  const add = (id, key, base, model) => {
    const secret = String(key || "").trim();
    if (secret) candidates.push({ id, key: secret, base, model });
  };
  add("openai", env.OPENAI_API_KEY, "https://api.openai.com/v1", env.OPENAI_MODEL || "gpt-4.1-mini");
  add("groq", env.GROQ_API_KEY, "https://api.groq.com/openai/v1", env.GROQ_MODEL || "openai/gpt-oss-20b");
  add("mistral", env.MISTRAL_API_KEY, "https://api.mistral.ai/v1", env.MISTRAL_MODEL || "mistral-small-latest");
  if (env.OPENROUTER_API_KEY) {
    add("openrouter", env.OPENROUTER_API_KEY, "https://openrouter.ai/api/v1", env.OPENROUTER_MODEL || "openrouter/auto");
  }
  const gigaCredentials = String(env.GIGACHAT_CREDENTIALS || env.GIGACHAT_AUTH_KEY || "").trim();
  const gigaAccessToken = String(env.GIGACHAT_ACCESS_TOKEN || "").trim();
  if (gigaCredentials || gigaAccessToken) {
    candidates.push({
      id: "gigachat",
      key: gigaAccessToken || gigaCredentials,
      credentials: gigaCredentials,
      base: "https://gigachat.devices.sberbank.ru/api/v1",
      // Резервный контур: прокси Layero на случай недоступности sberbank
      // (контракт эндпоинтов — docs/DEPLOY-LAYERO.md).
      ...(String(env.GIGACHAT_FALLBACK_BASE_URL || "").trim()
        ? {
            fallback_base: String(env.GIGACHAT_FALLBACK_BASE_URL).trim(),
            // Релей на RU-хостинге пускает только воркер (общий секрет).
            relay_secret: String(env.GIGACHAT_RELAY_SECRET || "").trim(),
          }
        : {}),
      model: env.GIGACHAT_MODEL || "GigaChat",
      scope: env.GIGACHAT_SCOPE || "GIGACHAT_API_PERS",
    });
  }
  if (env.GEMINI_API_KEY && (region !== "ru" || geminiProxyReady)) {
    candidates.push({
      id: "gemini",
      key: String(env.GEMINI_API_KEY).trim(),
      base: "https://generativelanguage.googleapis.com/v1beta",
      model: env.GEMINI_MODEL || "gemini-2.0-flash",
    });
  }
  if (userOverride && userOverride.key && userOverride.base && userOverride.model) {
    const custom = {
      id: "custom",
      key: String(userOverride.key).trim(),
      base: String(userOverride.base).trim(),
      model: String(userOverride.model).trim(),
      provider: userOverride.provider === "anthropic" ? "anthropic" : "openai_compatible",
    };
    if (userOverride.preferOwn || preferred === "custom") {
      candidates.unshift(custom);
    } else {
      candidates.push(custom);
    }
  }
  const configuredDefault = String(env.AI_CHAT_PRIMARY_PROVIDER || "groq").trim().toLowerCase();
  const first = preferred === "auto" ? configuredDefault : preferred;
  const index = candidates.findIndex((candidate) => candidate.id === first);
  if (index > 0) candidates.unshift(...candidates.splice(index, 1));
  if (preferred !== "auto" && index < 0) return [];
  return candidates;
}
/**
 * Глобальный fetch нельзя отрывать от его receiver: в workerd c nodejs_compat
 * вызов `const f = fetch; f(url)` мгновенно падает с TypeError (Illegal
 * invocation). Именно из-за этого внешние провайдеры «не отвечали»: ошибка
 * выглядела как сетевая и молча уводила запрос на Workers AI.
 */
function callFetch(fetcher, url, init) {
  if (typeof fetcher !== "function") throw new TypeError("fetch is not available");
  if (fetcher === fetch) return globalThis.fetch(url, init);
  return fetcher(url, init);
}
function aiTimeoutMs(cfg) {
  const remaining = Number(cfg?.deadline || 0) - Date.now();
  return Math.max(1, Math.min(EXTERNAL_CALL_TIMEOUT_MS, remaining || EXTERNAL_CALL_TIMEOUT_MS));
}
async function callGeminiCompletion(cfg, messages, fetcher, temperature = 0.25, report = () => {}, images = []) {
  const system = messages.filter((message) => message.role === "system").map((message) => message.content).join("\n\n");
  const contents = messages.filter((message) => message.role === "user" || message.role === "assistant").map((m) => m);
  // Vision: inline_data для последней user-реплики (data URL → base64).
  let lastUserIndex = -1;
  for (let i = contents.length - 1; i >= 0; i -= 1) if (contents[i].role === "user") { lastUserIndex = i; break; }
  const normalized = contents.map((entry, i) => {
    const parts = [{ text: String(entry.content || "") }];
    if (i === lastUserIndex && Array.isArray(images)) {
      for (const image of images) {
        const m = /^data:(image\/[a-z0-9.+-]+);base64,(.+)$/i.exec(String(image || ""));
        if (m) parts.push({ inline_data: { mime_type: m[1], data: m[2] } });
      }
    }
    return { role: entry.role === "assistant" ? "model" : "user", parts };
  });
  const endpoint = cfg.base.replace(/\/$/, "") + "/models/" + encodeURIComponent(cfg.model) + ":generateContent";
  let response;
  try {
    response = await callFetch(fetcher, endpoint, {
      method: "POST",
      headers: { "x-goog-api-key": cfg.key, "content-type": "application/json", accept: "application/json" },
      body: JSON.stringify({
        ...(system ? { systemInstruction: { parts: [{ text: system }] } } : {}),
        contents: normalized,
        generationConfig: { temperature, maxOutputTokens: 2500 },
      }),
      redirect: "manual",
      signal: AbortSignal.timeout(aiTimeoutMs(cfg)),
    });
  } catch {
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдер временно недоступен");
  }
  let payload = null;
  try { payload = await response.json(); } catch { /* handled below */ }
  if (!response.ok) {
    if (response.status === 429) throw new AiChatApiError(429, "AI_RATE_LIMIT", "ИИ-провайдер ограничил частоту запросов");
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдер временно недоступен");
  }
  const text = (payload?.candidates?.[0]?.content?.parts || []).map((part) => String(part.text || "")).join("").trim();
  if (!text) throw new AiChatApiError(502, "AI_EMPTY_RESPONSE", "ИИ-провайдер вернул пустой ответ");
  return { content: text, provider: cfg.id, model: cfg.model };
}

/**
 * Живой список моделей провайдера из его API (GET /models). Статический
 * PROVIDER_MODELS протухает — Groq удаляет старые модели (llama-3.3/3.1 к
 * ноябрю 2026 уже не отвечают), из-за чего выбранная в тьюторе модель падала
 * в фолбэк. Возвращает массив id или null, если провайдер не поддерживается
 * / не настроен / не ответил — вызывающий оставляет статический список.
 */
export async function listProviderModels(env = {}, providerId, fetcher = fetch) {
  const id = String(providerId || "").trim().toLowerCase();
  try {
    if (id === "groq" && env.GROQ_API_KEY) {
      const res = await callFetch(fetcher, "https://api.groq.com/openai/v1/models", {
        headers: { authorization: "Bearer " + String(env.GROQ_API_KEY).trim(), accept: "application/json" },
        signal: AbortSignal.timeout(3500),
      });
      if (!res.ok) return null;
      const payload = await res.json().catch(() => null);
      const ids = (Array.isArray(payload?.data) ? payload.data : []).map((m) => m?.id).filter((x) => typeof x === "string");
      // whisper/guard/tts/embed — не чат-модели тьютора.
      return ids.filter((x) => !/whisper|guard|tts|embed|distil|prompt-|playit/i.test(x));
    }
    if (id === "openai" && env.OPENAI_API_KEY) {
      const res = await callFetch(fetcher, "https://api.openai.com/v1/models", {
        headers: { authorization: "Bearer " + String(env.OPENAI_API_KEY).trim(), accept: "application/json" },
        signal: AbortSignal.timeout(3500),
      });
      if (!res.ok) return null;
      const payload = await res.json().catch(() => null);
      const ids = (Array.isArray(payload?.data) ? payload.data : []).map((m) => m?.id).filter((x) => typeof x === "string");
      return ids.filter((x) => /^gpt-/.test(x) && !/audio|realtime|image|transcribe/i.test(x));
    }
    if (id === "gigachat" && (env.GIGACHAT_CREDENTIALS || env.GIGACHAT_ACCESS_TOKEN)) {
      const credentials = String(env.GIGACHAT_CREDENTIALS || "").trim();
      let token = String(env.GIGACHAT_ACCESS_TOKEN || "").trim();
      if (!token && credentials) {
        const tr = await callFetch(fetcher, "https://ngw.devices.sberbank.ru:9443/api/v2/oauth", {
          method: "POST",
          headers: {
            authorization: "Basic " + credentials,
            "content-type": "application/x-www-form-urlencoded",
            RqUID: crypto.randomUUID(),
            accept: "application/json",
          },
          body: new URLSearchParams({ scope: env.GIGACHAT_SCOPE || "GIGACHAT_API_PERS" }),
          redirect: "manual",
          signal: AbortSignal.timeout(3500),
        });
        const tp = await tr.json().catch(() => null);
        if (!tr.ok || typeof tp?.access_token !== "string") return null;
        token = tp.access_token;
      }
      const res = await callFetch(fetcher, "https://gigachat.devices.sberbank.ru/api/v1/models", {
        headers: { authorization: "Bearer " + token, accept: "application/json" },
        signal: AbortSignal.timeout(3500),
      });
      if (!res.ok) return null;
      const payload = await res.json().catch(() => null);
      return (Array.isArray(payload?.data) ? payload.data : []).map((m) => m?.id).filter((x) => typeof x === "string");
    }
  } catch {
    return null;
  }
  return null;
}

/**
 * Кэш OAuth-токена GigaChat на время жизни изолята воркера (~25 мин).
 * Без него каждое сообщение платит двойной такс: 526 на прямом OAuth
 * (SSL Сбера) + повтор через релей. Ключ — credentials+scope+oauthUrl.
 */
const GIGA_TOKEN_CACHE = new Map();

async function gigachatAccessToken(cfg, fetcher, oauthUrl, report, started) {
  const preIssued = String(cfg.key || "").trim();
  if (!String(cfg.credentials || "").trim() && preIssued) return preIssued;
  const cacheKey = String(cfg.credentials || "") + "|" + String(cfg.scope || "") + "|" + oauthUrl;
  const cached = GIGA_TOKEN_CACHE.get(cacheKey);
  if (cached && cached.expires > Date.now() + 60_000) return cached.token;

  let tokenResponse;
  try {
    tokenResponse = await callFetch(fetcher, oauthUrl, {
      method: "POST",
      headers: {
        authorization: "Basic " + String(cfg.credentials).trim(),
        "content-type": "application/x-www-form-urlencoded",
        RqUID: crypto.randomUUID(),
        accept: "application/json",
        // Релей на Layero требует общий секрет (когда настроен).
        ...(cfg.relay_secret ? { "x-medbiohim-internal": String(cfg.relay_secret) } : {}),
      },
      body: new URLSearchParams({ scope: cfg.scope || "GIGACHAT_API_PERS" }),
      redirect: "manual",
      signal: AbortSignal.timeout(aiTimeoutMs(cfg)),
    });
  } catch (error) {
    report({ id: "gigachat", outcome: "network", status: 0, stage: "oauth", ms: Date.now() - started, error: String(error?.name || "error"), detail: String(error?.message || "").slice(0, 160) });
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "GigaChat временно недоступен");
  }
  let tokenPayload = null;
  try { tokenPayload = await tokenResponse.json(); } catch { /* handled below */ }
  if (!tokenResponse.ok || typeof tokenPayload?.access_token !== "string") {
    report({ id: "gigachat", outcome: "http", status: tokenResponse.status, stage: "oauth", ms: Date.now() - started });
    if (tokenResponse.status === 429) throw new AiChatApiError(429, "AI_RATE_LIMIT", "GigaChat ограничил частоту запросов");
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "GigaChat временно недоступен");
  }
  const ttlMs = Math.min(Number(tokenPayload?.expires_at) * 1000 - Date.now() || 25 * 60_000, 25 * 60_000);
  GIGA_TOKEN_CACHE.set(cacheKey, { token: tokenPayload.access_token, expires: Date.now() + Math.max(60_000, ttlMs) });
  return tokenPayload.access_token;
}

/**
 * Один заход GigaChat: OAuth (если нет готового токена) + chat/completions.
 * base/oauthUrl параметризованы: тот же код работает через прокси Layero
 * (резервный контур), где оба эндпоинта лежат под одним origin.
 */
async function gigachatAttempt(cfg, messages, fetcher, temperature, report, started, base, oauthUrl) {
  let accessToken = String(cfg.key || "").trim();
  if (!String(cfg.credentials || "").trim() && !accessToken) {
    throw new AiChatApiError(503, "AI_PROVIDER_UNAVAILABLE", "GigaChat не настроен");
  }
  if (!String(cfg.credentials || "").trim() && accessToken) {
    // A pre-issued access token can be used directly; credentials are never returned to the caller.
  } else {
    // OAuth с кэшем токена: без него каждое сообщение платило двойной такс
    // (526 прямого OAuth + повтор через релей).
    accessToken = await gigachatAccessToken(cfg, fetcher, oauthUrl, report, started);
  }
  let response;
  try {
    response = await callFetch(fetcher, base.replace(/\/$/, "") + "/chat/completions", {
      method: "POST",
      headers: {
        authorization: "Bearer " + accessToken,
        "content-type": "application/json",
        accept: "application/json",
        ...(cfg.relay_secret ? { "x-medbiohim-internal": String(cfg.relay_secret) } : {}),
      },
      body: JSON.stringify({ model: cfg.model, temperature, max_tokens: 2500, messages }),
      redirect: "manual",
      signal: AbortSignal.timeout(aiTimeoutMs(cfg)),
    });
  } catch (error) {
    report({ id: "gigachat", outcome: "network", status: 0, stage: "chat", ms: Date.now() - started, error: String(error?.name || "error"), detail: String(error?.message || "").slice(0, 160) });
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "GigaChat временно недоступен");
  }
  let payload = null;
  try { payload = await response.json(); } catch { /* handled below */ }
  if (!response.ok) {
    report({ id: "gigachat", outcome: "http", status: response.status, stage: "chat", ms: Date.now() - started });
    if (response.status === 429) throw new AiChatApiError(429, "AI_RATE_LIMIT", "GigaChat ограничил частоту запросов");
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "GigaChat временно недоступен");
  }
  report({ id: "gigachat", outcome: "ok", status: response.status, stage: "chat", ms: Date.now() - started });
  const text = payload?.choices?.[0]?.message?.content;
  if (typeof text !== "string" || !text.trim()) throw new AiChatApiError(502, "AI_EMPTY_RESPONSE", "ИИ-провайдер вернул пустой ответ");
  return { content: text.trim(), provider: cfg.id, model: String(payload?.model || cfg.model) };
}

/**
 * Прямой GigaChat, при отказе основного канала — прокси Layero
 * (env GIGACHAT_FALLBACK_BASE_URL, контракт в docs/DEPLOY-LAYERO.md).
 * Повтор только по недоступности: 429 и настройки не ретраятся.
 */
async function callGigaChatCompletion(cfg, messages, fetcher, temperature = 0.25, report = () => {}) {
  const started = Date.now();
  const fallbackBase = String(cfg.fallback_base || "").trim();
  try {
    return await gigachatAttempt(cfg, messages, fetcher, temperature, report, started, cfg.base, "https://ngw.devices.sberbank.ru:9443/api/v2/oauth");
  } catch (error) {
    if (!fallbackBase || error?.code !== "AI_UPSTREAM_UNAVAILABLE") throw error;
    report({ id: "gigachat", outcome: "fallback", status: 0, stage: "chat", ms: Date.now() - started, detail: "основной канал недоступен — резервный прокси" });
    return gigachatAttempt(cfg, messages, fetcher, temperature, report, started, fallbackBase, fallbackBase.replace(/\/$/, "") + "/oauth");
  }
}

/**
 * Claude (Anthropic Messages API) — формат для BYOM-провайдера "anthropic":
 * ключ в x-api-key, system — отдельным полем, max_tokens обязателен,
 * ответ — массив content-блоков.
 */
async function callClaudeCompletion(cfg, messages, fetcher, temperature = 0.25, report = () => {}) {
  const endpoint = cfg.base.replace(/\/$/, "") + "/v1/messages";
  const system = messages.filter((message) => message.role === "system").map((message) => message.content).join("\n\n");
  const chat = messages.filter((message) => message.role !== "system");
  const started = Date.now();
  let response;
  try {
    response = await callFetch(fetcher, endpoint, {
      method: "POST",
      headers: {
        "x-api-key": cfg.key,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
        accept: "application/json",
      },
      body: JSON.stringify({
        model: cfg.model,
        max_tokens: 2500,
        temperature,
        ...(system ? { system } : {}),
        messages: chat.map((message) => ({ role: message.role, content: message.content })),
      }),
      redirect: "manual",
      signal: AbortSignal.timeout(aiTimeoutMs(cfg)),
    });
  } catch (error) {
    report({ id: cfg.id, outcome: "network", status: 0, ms: Date.now() - started, error: String(error?.name || "error"), detail: String(error?.message || "").slice(0, 160) });
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдер временно недоступен");
  }
  let payload = null;
  try { payload = await response.json(); } catch { /* handled below */ }
  if (!response.ok) {
    report({ id: cfg.id, outcome: "http", status: response.status, ms: Date.now() - started });
    if (response.status === 429) throw new AiChatApiError(429, "AI_RATE_LIMIT", "ИИ-провайдер ограничил частоту запросов");
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдер временно недоступен");
  }
  const text = Array.isArray(payload?.content)
    ? payload.content.filter((block) => block?.type === "text").map((block) => String(block.text || "")).join("").trim()
    : "";
  if (!text) {
    report({ id: cfg.id, outcome: "empty", status: response.status, ms: Date.now() - started });
    throw new AiChatApiError(502, "AI_EMPTY_RESPONSE", "ИИ-провайдер вернул пустой ответ");
  }
  report({ id: cfg.id, outcome: "ok", status: response.status, ms: Date.now() - started });
  return { content: text, provider: cfg.id, model: String(payload?.model || cfg.model) };
}

/**
 * Мультимодальность: превратить последнюю пользовательскую реплику в parts с
 * картинками (OpenAI-совместимый формат image_url). Поддерживают gemini
 * (отдельный путь inline_data), openai, groq, openrouter, mistral и BYOM
 * openai_compatible; gigachat — нет.
 */
function toMultimodalMessages(messages, images) {
  const parts = [];
  for (const image of images) {
    const m = /^data:(image\/[a-z0-9.+-]+);base64,(.+)$/i.exec(String(image || ""));
    if (m) parts.push({ type: "image_url", image_url: { url: String(image) } });
  }
  if (!parts.length) return messages;
  const out = messages.map((m) => ({ ...m }));
  for (let i = out.length - 1; i >= 0; i -= 1) {
    if (out[i].role === "user") {
      out[i] = { role: "user", content: [{ type: "text", text: String(out[i].content || "") }, ...parts] };
      break;
    }
  }
  return out;
}

async function callAiCompletion(cfg, messages, fetcher, temperature = 0.25, report = () => {}, options = {}) {
  const images = Array.isArray(options?.images) ? options.images.filter(Boolean) : [];
  if (cfg.id === "gemini") return callGeminiCompletion(cfg, messages, fetcher, temperature, report, images);
  if (cfg.id === "gigachat") return callGigaChatCompletion(cfg, messages, fetcher, temperature, report);
  if (cfg.id === "custom" && cfg.provider === "anthropic") return callClaudeCompletion(cfg, messages, fetcher, temperature, report);
  const endpoint = cfg.base.replace(/\/$/, "") + "/chat/completions";
  const started = Date.now();
  // Vision: у openai/groq/openrouter/mistral и BYOM openai_compatible —
  // image_url parts. Если провайдер не поддерживает конкретную модель, он
  // вернёт 4xx и цепочка уйдёт в фолбэк/дефолт как обычно.
  const payloadMessages = images.length ? toMultimodalMessages(messages, images) : messages;
  let response;
  try {
    response = await callFetch(fetcher, endpoint, {
      method: "POST",
      headers: {
        authorization: "Bearer " + cfg.key,
        "content-type": "application/json",
        accept: "application/json",
        ...(cfg.id === "openrouter" ? { "HTTP-Referer": "https://medbiohim.vercel.app", "X-Title": "Medbiohim" } : {}),
      },
      body: JSON.stringify({ model: cfg.model, temperature, max_tokens: 2500, messages: payloadMessages }),
      redirect: "manual",
      signal: AbortSignal.timeout(aiTimeoutMs(cfg)),
    });
  } catch (error) {
    report({ id: cfg.id, outcome: "network", status: 0, ms: Date.now() - started, error: String(error?.name || "error"), detail: String(error?.message || "").slice(0, 160) });
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдер временно недоступен");
  }
  let payload = null;
  try { payload = await response.json(); } catch { /* handled below */ }
  if (!response.ok) {
    report({ id: cfg.id, outcome: "http", status: response.status, ms: Date.now() - started });
    if (response.status === 429) throw new AiChatApiError(429, "AI_RATE_LIMIT", "ИИ-провайдер ограничил частоту запросов");
    // Do not expose provider response bodies, keys, or upstream diagnostics.
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдер временно недоступен");
  }
  const text = payload?.choices?.[0]?.message?.content;
  if (typeof text !== "string" || !text.trim()) {
    report({ id: cfg.id, outcome: "empty", status: response.status, ms: Date.now() - started });
    throw new AiChatApiError(502, "AI_EMPTY_RESPONSE", "ИИ-провайдер вернул пустой ответ");
  }
  report({ id: cfg.id, outcome: "ok", status: response.status, ms: Date.now() - started });
  return { content: text.trim(), provider: cfg.id, model: String(payload?.model || cfg.model) };
}

/**
 * Stateless completion for server-side grounded workflows (e.g. legacy Tutor/RAG).
 * It reuses the same configured-provider order and safe fallback behavior as chat
 * without writing conversations or messages to Supabase.
 */
export async function generateAiCompletion(env = {}, messages = [], preferredProvider = "auto", fetcher = fetch, options = {}) {
  // Режим ответа выбирает вызывающий: «точный» (0.2, RAG обязателен) или
  // «быстрый» (0.5, без контекста). Без явного значения — прежние 0.25.
  const requestedTemperature = Number(options?.temperature);
  const temperature = Number.isFinite(requestedTemperature)
    ? Math.min(1, Math.max(0, requestedTemperature))
    : 0.25;
  if (!Array.isArray(messages) || messages.length < 1 || messages.length > 24) {
    throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректный контекст для ИИ");
  }
  const safeMessages = [];
  for (const entry of messages) {
    if (!entry || typeof entry !== "object" || !["system", "user", "assistant"].includes(entry.role)
      || typeof entry.content !== "string" || !entry.content.trim()) {
      throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректное сообщение в контексте ИИ");
    }
    safeMessages.push({
      role: entry.role,
      content: entry.content.slice(0, 12_000),
    });
  }

  const candidates = getAiCompletionCandidates(env, preferredProvider, options?.userOverride);
  if (!candidates.length) {
    const status = getAiProviderStatus(env);
    const preferred = String(preferredProvider || "auto").trim().toLowerCase();
    const known = status.providers?.[preferred];
    if (preferred !== "auto" && known && !known.available) {
      throw new AiChatApiError(503, "AI_PROVIDER_UNAVAILABLE", known.reason || "Выбранный ИИ-провайдер не настроен");
    }
    throw new AiChatApiError(503, "AI_NOT_CONFIGURED", "Не настроен доступный ИИ-провайдер");
  }

  // Выбор модели студентом: подменяем модель только у кандидата выбранного
  // провайдера (preferred === "auto" — без подмены, цепочка сама выбирает).
  const preferredProviderKey = String(preferredProvider || "auto").trim().toLowerCase();
  const modelOverride = resolveProviderModel(env, preferredProviderKey, options?.model);
  if (modelOverride && preferredProviderKey !== "auto") {
    for (const candidate of candidates) {
      if (candidate.id === preferredProviderKey) {
        // Дефолт запоминаем: если провайдер снимет выбранную модель (400/404),
        // цепочка сначала откатится к дефолту этого же провайдера.
        candidate.defaultModel = candidate.model;
        candidate.model = modelOverride;
      }
    }
  }

  // Провайдеры с недавними отказами (пробы Redis) уходят в конец цепочки:
  // пользователь не должен ждать 403/429 заведомо больных upstream'ов.
  const unhealthy = new Set(
    (Array.isArray(options?.unhealthy) ? options.unhealthy : []).map((x) => String(x).toLowerCase()),
  );
  if (unhealthy.size) {
    candidates.sort((a, b) => Number(unhealthy.has(a.id)) - Number(unhealthy.has(b.id)));
  }

  const report = typeof options?.onAttempt === "function" ? options.onAttempt : () => {};
  let lastError = null;
  const deadline = Date.now() + EXTERNAL_TOTAL_BUDGET_MS;
  // Картинки (data URLs) для мультимодальных провайдеров: строгая валидация.
  const images = (Array.isArray(options?.images) ? options.images : [])
    .filter((x) => typeof x === "string" && /^data:image\/[a-z0-9.+-]+;base64,/.test(x.slice(0, 64)) && x.length <= 6_000_000)
    .slice(0, 4);
  for (const candidate of candidates) {
    try {
      if (deadline - Date.now() <= 250) break;
      return await callAiCompletion({ ...candidate, deadline }, safeMessages, fetcher, temperature, report, { images });
    } catch (error) {
      lastError = error;
      // Выбранная студентом модель снята провайдером (400/404 = ошибка модели,
      // а не канала): откатываемся к дефолтной модели ЭТОГО же провайдера,
      // прежде чем ронять весь провайдер в фолбэк.
      if (candidate.defaultModel && candidate.model !== candidate.defaultModel
        && [400, 404].includes(Number(error?.status || 0))) {
        try {
          return await callAiCompletion(
            { ...candidate, model: candidate.defaultModel, deadline },
            safeMessages, fetcher, temperature, report, { images },
          );
        } catch (retryError) {
          lastError = retryError;
        }
      }
      // Без этой строки отказ провайдера исчезал молча: в /ai/providers ключ
      // есть, значит «настроен», а ответ приходит от следующего кандидата или
      // от Workers AI — и причину видно только по логам воркера.
      console.warn("[ai:provider-failed]", JSON.stringify({
        provider: candidate.id,
        code: String(error?.code || error?.name || "ERROR"),
        status: Number(error?.status || 0),
      }));
    }
  }
  if (lastError instanceof AiChatApiError) throw lastError;
  throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдеры временно недоступны");
}

/**
 * Runs a real provider request. Supabase rows always use the caller JWT and are
 * explicitly scoped to that caller; provider credentials remain server-only.
 */
export async function sendAiMessage(request, env, userId, conversationId, input = {}, fetcher = fetch) {
  if (!userId || typeof userId !== "string") throw new AiChatApiError(401, "UNAUTHORIZED", "Authentication required");
  const id = uuidOr404(conversationId);
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw new AiChatApiError(422, "VALIDATION_ERROR", "Некорректное тело запроса");
  }
  const content = typeof input.content === "string" ? input.content.trim() : "";
  if (!content || content.length > 12000) {
    throw new AiChatApiError(422, "VALIDATION_ERROR", "Сообщение должно содержать от 1 до 12000 символов");
  }
  if (env.AI_CHAT_LIMITER && typeof env.AI_CHAT_LIMITER.limit === "function") {
    const limited = await env.AI_CHAT_LIMITER.limit({ key: "ai-chat:" + userId });
    if (!limited?.success) throw new AiChatApiError(429, "RATE_LIMIT", "Слишком много запросов к ИИ. Подождите немного.");
  }

  const conversationParams = new URLSearchParams({
    select: "id,user_id,title,provider,model,subject_slug,created_at,updated_at",
    id: "eq." + id,
    user_id: "eq." + userId,
    limit: "1",
  });
  const conversations = await rest(request, env, userId, "ai_conversations", conversationParams, {}, fetcher);
  const conversation = Array.isArray(conversations) ? conversations[0] : null;
  if (!conversation) throw new AiChatApiError(404, "NOT_FOUND", "Ресурс ИИ-сервиса недоступен");

  const subjectSlug = input.subject_slug === undefined
    ? (conversation.subject_slug || null)
    : validateSubjectSlug(input.subject_slug);
  const requestedProvider = input.provider || conversation.provider || "auto";
  const candidates = getAiCompletionCandidates(env, requestedProvider);
  if (!candidates.length) {
    const status = getAiProviderStatus(env);
    const chosen = String(requestedProvider).toLowerCase();
    const known = status.providers[chosen];
    if (known && !known.available) {
      throw new AiChatApiError(503, "AI_PROVIDER_UNAVAILABLE", known.reason || "Выбранный ИИ-провайдер не настроен");
    }
    throw new AiChatApiError(503, "AI_NOT_CONFIGURED", "Не настроен доступный ИИ-провайдер");
  }

  const userRows = await rest(request, env, userId, "ai_messages", new URLSearchParams({ select: "id,role,content,provider,model,metadata,created_at" }), {
    method: "POST",
    body: {
      conversation_id: id,
      user_id: userId,
      role: "user",
      content,
    },
    prefer: "return=representation",
  }, fetcher);
  const userMessage = Array.isArray(userRows) ? userRows[0] : null;

  const historyParams = new URLSearchParams({
    select: "role,content,created_at",
    conversation_id: "eq." + id,
    user_id: "eq." + userId,
    order: "created_at.desc",
    limit: "40",
  });
  const history = await rest(request, env, userId, "ai_messages", historyParams, {}, fetcher);
  const messages = [{
    role: "system",
    content: "Ты — ИИ-тьютор образовательной платформы «Медбиохим». Отвечай по-русски, понятно студенту медицинского вуза. Объясняй последовательно, различай подтверждённые факты и неопределённость. Для учебных вопросов выделяй ключевые понятия, механизм и краткий вывод. Не выдумывай источники и не подменяй клинические рекомендации.",
  }];
  if (subjectSlug) messages[0].content += " Текущий предмет: " + subjectSlug + ".";
  for (const item of (Array.isArray(history) ? history : []).reverse()) {
    const role = String(item.role || "");
    if ((role === "user" || role === "assistant") && typeof item.content === "string") {
      messages.push({ role, content: item.content.slice(0, 12000) });
    }
  }
  // Some PostgREST deployments may not return the inserted message immediately.
  if (!messages.some((item) => item.role === "user" && item.content === content)) {
    messages.push({ role: "user", content });
  }

  let completion = null;
  let lastProviderError = null;
  for (const candidate of candidates) {
    try {
      completion = await callAiCompletion(candidate, messages, fetcher);
      break;
    } catch (error) {
      lastProviderError = error;
      console.warn("[ai:provider-failed]", JSON.stringify({
        provider: candidate.id,
        code: String(error?.code || error?.name || "ERROR"),
        status: Number(error?.status || 0),
      }));
      // Fail over only to other configured providers; never expose upstream errors.
    }
  }
  if (!completion) {
    if (lastProviderError instanceof AiChatApiError) throw lastProviderError;
    throw new AiChatApiError(502, "AI_UPSTREAM_UNAVAILABLE", "ИИ-провайдеры временно недоступны");
  }
  const assistantParams = new URLSearchParams({ select: "id,role,content,provider,model,metadata,created_at" });
  const assistantRows = await rest(request, env, userId, "ai_messages", assistantParams, {
    method: "POST",
    body: {
      conversation_id: id,
      user_id: userId,
      role: "assistant",
      content: completion.content,
      provider: completion.provider,
      model: completion.model,
      metadata: { mode: "api" },
    },
    prefer: "return=representation",
  }, fetcher);
  const title = String(conversation.title || "Новый чат") === "Новый чат"
    ? content.replace(/\s+/gu, " ").slice(0, 80)
    : conversation.title;
  const updateParams = new URLSearchParams({ id: "eq." + id, user_id: "eq." + userId });
  try {
    await rest(request, env, userId, "ai_conversations", updateParams, {
      method: "PATCH",
      body: {
        title,
        provider: completion.provider,
        model: completion.model,
        subject_slug: subjectSlug,
        updated_at: new Date().toISOString(),
      },
      prefer: "return=minimal",
    }, fetcher);
  } catch { /* Response is still useful if the title update is rejected by an older schema. */ }
  return {
    conversation: { ...conversation, title, provider: completion.provider, model: completion.model, subject_slug: subjectSlug },
    user_message: userMessage || { role: "user", content },
    assistant_message: (Array.isArray(assistantRows) ? assistantRows[0] : null) || {
      role: "assistant", content: completion.content, provider: completion.provider, model: completion.model,
    },
  };
}
